@Test
public void testDecoding() throws IOException {
    PersonnelRecord expected = DataTest.createSamplePersonnel();
    byte[] data = DataTest.createSammplePersonnelEncodingData();
    Asn1.parseAndDump(data);
    PersonnelRecord decoded = new PersonnelRecord();
    decoded.decode(data);
    Asn1.dump(decoded);
    assertThat(decoded.getName().getGivenName()).isEqualTo(expected.getName().getGivenName());
    assertThat(decoded.getName().getInitial()).isEqualTo(expected.getName().getInitial());
    assertThat(decoded.getName().getFamilyName()).isEqualTo(expected.getName().getFamilyName());
    assertThat(decoded.getDateOfHire().getValue().getValue()).isEqualTo(expected.getDateOfHire().getValue().getValue());
    assertThat(decoded.getTitle()).isEqualTo(expected.getTitle());
    assertThat(decoded.getEmployeeNumber().getValue().getValue()).isEqualTo(expected.getEmployeeNumber().getValue().getValue());
    assertThat(decoded.getNameOfSpouse().getGivenName()).isEqualTo(expected.getNameOfSpouse().getGivenName());
    assertThat(decoded.getNameOfSpouse().getInitial()).isEqualTo(expected.getNameOfSpouse().getInitial());
    assertThat(decoded.getNameOfSpouse().getFamilyName()).isEqualTo(expected.getNameOfSpouse().getFamilyName());
    assertThat(decoded.getChildren().getElements().size()).isEqualTo(expected.getChildren().getElements().size());
    assertThat(decoded.getChildren().getElements().get(0).getName().getGivenName()).isEqualTo(expected.getChildren().getElements().get(0).getName().getGivenName());
    assertThat(decoded.getChildren().getElements().get(0).getName().getInitial()).isEqualTo(expected.getChildren().getElements().get(0).getName().getInitial());
    assertThat(decoded.getChildren().getElements().get(0).getName().getFamilyName()).isEqualTo(expected.getChildren().getElements().get(0).getName().getFamilyName());
    assertThat(decoded.getChildren().getElements().get(0).getDateOfBirth().getValue().getValue()).isEqualTo(expected.getChildren().getElements().get(0).getDateOfBirth().getValue().getValue());
    assertThat(decoded.getChildren().getElements().get(1).getName().getGivenName()).isEqualTo(expected.getChildren().getElements().get(1).getName().getGivenName());
    assertThat(decoded.getChildren().getElements().get(1).getName().getInitial()).isEqualTo(expected.getChildren().getElements().get(1).getName().getInitial());
    assertThat(decoded.getChildren().getElements().get(1).getName().getFamilyName()).isEqualTo(expected.getChildren().getElements().get(1).getName().getFamilyName());
    assertThat(decoded.getChildren().getElements().get(1).getDateOfBirth().getValue().getValue()).isEqualTo(expected.getChildren().getElements().get(1).getDateOfBirth().getValue().getValue());
}

