@Test
public void testTaggingEncodingOption() throws IOException {
    Type1 aType1 = new Type1(TEST_STRING);
    Type2 aType2 = new Type2(aType1);
    Type3 aType3 = new Type3(aType2);
    assertThat(aType1.encode()).isEqualTo(TYPE1_EXPECTED_BYTES);
    assertThat(TYPE2_EXPECTED_BYTES).isEqualTo(// for Type2
    aType1.taggedEncode(TaggingOption.newImplicitAppSpecific(3)));
    assertThat(TYPE3_EXPECTED_BYTES).isEqualTo(// for Type3
    aType2.taggedEncode(TaggingOption.newExplicitContextSpecific(2)));
    assertThat(TYPE4_EXPECTED_BYTES).isEqualTo(// for Type4
    aType3.taggedEncode(TaggingOption.newImplicitAppSpecific(7)));
    assertThat(TYPE5_EXPECTED_BYTES).isEqualTo(// for Type5
    aType2.taggedEncode(TaggingOption.newImplicitContextSpecific(2)));
}

