public void testStoringSGT() throws Exception {
    TgtTicket tgt = getKrbClient().requestTgt(getClientPrincipal(), getClientPassword());
    assertThat(tgt).isNotNull();
    SgtTicket tkt = getKrbClient().requestSgt(tgt, getServerPrincipal());
    assertThat(tkt).isNotNull();
    File ccFile = new File("target/cache.cc");
    if (ccFile.exists()) {
        ccFile.delete();
    }
    try {
        // Test storing the SGT and not the TGT
        getKrbClient().storeTicket(tkt, ccFile);
    } catch (Throwable t) {
        t.printStackTrace();
    }
}

@Test
public void testGss() throws Exception {
    Subject clientSubject = loginClientUsingTicketCache();
    Set<Principal> clientPrincipals = clientSubject.getPrincipals();
    Assertions.assertFalse(clientPrincipals.isEmpty());
    // Get the TGT
    Set<KerberosTicket> privateCredentials = clientSubject.getPrivateCredentials(KerberosTicket.class);
    Assertions.assertFalse(privateCredentials.isEmpty());
    KerberosTicket tgt = privateCredentials.iterator().next();
    Assertions.assertNotNull(tgt);
    // Get the service ticket
    KerberosClientExceptionAction action = new KerberosClientExceptionAction(clientPrincipals.iterator().next(), getServerPrincipal());
    byte[] kerberosToken = (byte[]) Subject.doAs(clientSubject, action);
    Assertions.assertNotNull(kerberosToken);
    validateServiceTicket(kerberosToken);
}

